import { isAbsolute } from "node:path";
import { randomUUID } from "node:crypto";
import type { Clock } from "../clock.js";import type { HubStore } from "../store.js";
import type { DeliveryRouter } from "./delivery-router.js";import { CoordinationError } from "./errors.js";import { ChangeNotifier } from "./notifier.js";import type { TaskStore } from "./task-store.js";import type { CoordinationMessage,CoordinationTask,JsonValue,TaskListFilters,TaskPage } from "./types.js";import { WorkerProviderCatalog } from "./worker-providers.js";
const DEFAULT=30*60_000,MAX=2*60*60_000;const terminal=new Set(["completed","failed","canceled","rejected"]);
export class CoordinationService {
 private readonly registry:HubStore;private readonly tasks:TaskStore;private readonly router:DeliveryRouter|undefined;private readonly providers:WorkerProviderCatalog;private readonly clock:Clock;private readonly notifier:ChangeNotifier;
 constructor(o:{registry:HubStore;tasks:TaskStore;router?:DeliveryRouter;providers?:WorkerProviderCatalog;clock:Clock;notifier?:ChangeNotifier}){this.registry=o.registry;this.tasks=o.tasks;this.router=o.router;this.providers=o.providers??new WorkerProviderCatalog();this.clock=o.clock;this.notifier=o.notifier??new ChangeNotifier()}
 createExistingSessionTask(source:string,input:{targetSessionId:string;contextId?:string;deadlineAt?:number;message:CoordinationMessage}):CoordinationTask{this.requireSource(source);const deadlineAt=this.deadline(input.deadlineAt),contextId=input.contextId||randomUUID(),target=this.registry.getSession(input.targetSessionId);const data={sourceSessionId:source,targetSessionId:input.targetSessionId,contextId,deadlineAt,message:{...input.message,role:"source" as const}};const task=!target||!target.metadata.acceptsTaskDelivery?this.tasks.createRejectedTask(data,"TARGET_REJECTED"):this.tasks.createExistingTask(data).task;if(task.targetSessionId)this.router?.notifyTarget(task.targetSessionId);return task}
 createWorkerTask(source:string,input:{provider:string;cwd:string;options:Record<string,JsonValue>;contextId?:string;deadlineAt?:number;message:CoordinationMessage}):CoordinationTask{this.requireSource(source);if(!/^[a-z0-9_-]{1,64}$/.test(input.provider)||!isAbsolute(input.cwd)||input.cwd.length>4096||Buffer.byteLength(JSON.stringify(input.options))>16384)throw new CoordinationError("UNSUPPORTED_CONTENT","Worker target is invalid",400);const made=this.tasks.createWorkerTask({sourceSessionId:source,provider:input.provider,cwd:input.cwd,options:input.options,contextId:input.contextId||randomUUID(),deadlineAt:this.deadline(input.deadlineAt),message:{...input.message,role:"source"}});void(async()=>{try{const r=await this.providers.start(input.provider,{taskId:made.task.id,launchToken:made.launchToken,cwd:input.cwd,options:input.options,deadlineAt:made.task.deadlineAt});this.tasks.recordWorkerStarted(made.task.id,r.launchId)}catch(e){this.tasks.recordWorkerStartFailed(made.task.id,e instanceof CoordinationError&&e.code==="WORKER_PROVIDER_NOT_FOUND"?e.code:"WORKER_START_FAILED");this.notifier.notify(made.task.id)}})().catch(()=>undefined);return made.task}
 bindWorkerSession(token:string,session:string):CoordinationTask{const target=this.registry.getSession(session);if(!target?.metadata.acceptsTaskDelivery)throw new CoordinationError("LAUNCH_TOKEN_INVALID","Launch token is invalid or expired",401);const task=this.tasks.bindWorkerSession(token,session);this.router?.notifyTarget(session);return task}
 appendMessage(source:string,id:string,m:CoordinationMessage):CoordinationTask{const task=this.owned(source,id);this.tasks.appendSourceMessage(task.id,{...m,role:"source"});if(task.targetSessionId)this.router?.notifyTarget(task.targetSessionId);return this.tasks.getTask(id)!}
 getTask(source:string,id:string){const t=this.tasks.getTask(id);return t?.sourceSessionId===source?t:undefined} listTasks(source:string,f:TaskListFilters):TaskPage{return this.tasks.listTasks(source,f)} coordinationMessages(id:string,historyLength?:number){return this.tasks.listMessages(id,historyLength)}
 cancelTask(source:string,id:string):CoordinationTask{this.owned(source,id);const task=this.tasks.requestCancellation(source,id,this.clock.now());this.notifier.notify(id);if(task.targetSessionId)this.router?.notifyTarget(task.targetSessionId);const launch=this.tasks.getWorkerLaunch(id);if(task.cancellationRequested&&launch?.launchId)void this.providers.cancel(launch.provider,launch.launchId).catch(()=>undefined);return task}
 async waitForTerminal(source:string,id:string,signal?:AbortSignal):Promise<CoordinationTask>{while(true){const t=this.owned(source,id);if(terminal.has(t.state)||signal?.aborted)return t;const g=this.notifier.generation(id);await this.notifier.wait(id,g,30_000,signal)}}
 onSessionClosed(id:string):void{for(const task of [...this.tasks.closeSourceSession(id,this.clock.now()),...this.tasks.closeTargetSession(id,this.clock.now())])this.notifier.notify(task)}
 expireDeadlines():string[]{const ids=this.tasks.expireDeadlines(this.clock.now());ids.forEach(id=>this.notifier.notify(id));return ids}
 expireWorkerLaunches():string[]{const rows=this.tasks.listExpiredWorkerLaunches(this.clock.now());for(const r of rows){this.tasks.recordWorkerStartFailed(r.taskId,"WORKER_START_FAILED");if(r.launchId)void this.providers.cancel(r.provider,r.launchId).catch(()=>undefined);this.notifier.notify(r.taskId)}return rows.map(r=>r.taskId)}
 countRetainedTasks(){return this.tasks.countRetainedTasks()} taskNotFoundMetadata(id:string){const uuid="[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}";return new RegExp(`^${uuid}:${uuid}$`).test(id)&&!this.tasks.isTaskFromCurrentInstance(id)?{reason:"coordinator_restarted"}:undefined} close(){this.notifier.close();this.tasks.close()}
 private requireSource(id:string){if(!this.registry.getSession(id))throw new CoordinationError("TASK_NOT_FOUND","Source session not found",404)} private owned(s:string,id:string){const t=this.getTask(s,id);if(!t)throw new CoordinationError("TASK_NOT_FOUND","Task not found",404);return t} private deadline(value?:number){const now=this.clock.now(),d=value??now+DEFAULT;if(d<=now||d>now+MAX)throw new CoordinationError("DEADLINE_EXCEEDED","Task deadline is outside the allowed range",400);return d}
}
