import { timingSafeEqual } from "node:crypto";import type { IncomingMessage,ServerResponse } from "node:http";import type { TSchema } from "typebox";import { Check } from "typebox/value";
export class HttpError extends Error{constructor(readonly status:number,readonly code:string,message:string){super(message)}}
export const MAX_BODY_BYTES=1_048_576;
export async function readJsonBody(req:IncomingMessage):Promise<unknown>{const chunks:Buffer[]=[];let total=0;for await(const raw of req){const c=Buffer.from(raw);total+=c.length;if(total>MAX_BODY_BYTES)throw new HttpError(413,"PAYLOAD_TOO_LARGE","Request body too large");chunks.push(c)}if(!total)return{};try{return JSON.parse(Buffer.concat(chunks).toString("utf8"))}catch{throw new HttpError(400,"INVALID_JSON","Request body must be valid JSON")}}
export function validateBody<T extends TSchema>(schema:T,value:unknown):void{if(!Check(schema,value))throw new HttpError(400,"INVALID_REQUEST","Request body failed validation")}
export function sendJson(res:ServerResponse,status:number,payload:unknown,contentType="application/json"){res.statusCode=status;res.setHeader("content-type",contentType);res.end(JSON.stringify(payload))}
export function bearerToken(req:IncomingMessage){const h=req.headers.authorization;return typeof h==="string"&&h.startsWith("Bearer ")?h.slice(7):undefined}
export function authenticateRoot(req:IncomingMessage,expected:Buffer){const token=Buffer.from(`Bearer ${bearerToken(req)??""}`);if(token.length!==expected.length||!timingSafeEqual(token,expected))throw new HttpError(401,"UNAUTHORIZED","Invalid bearer token")}
export function safePathname(url?:string){try{return new URL(url??"/","http://127.0.0.1").pathname}catch{return"/"}}
export function safeLogPath(method:string,url?:string){const p=safePathname(url);if(/^\/tasks\/[^/]+(?::cancel)?$/.test(p))return p.endsWith(":cancel")?"/tasks/:taskId:cancel":"/tasks/:taskId";if(/^\/v2\/sessions\/[^/]+\/tasks\/[^/]+/.test(p))return"/v2/sessions/:sessionId/tasks/:taskId";if(/^\/v2\/sessions\/[^/]+/.test(p))return"/v2/sessions/:sessionId";return["/v2/health","/v2/sessions","/v2/query","/message:send","/tasks","/.well-known/agent-card.json"].includes(p)?p:"/unmatched"}
