export async function handleHubRequestInternal(req:http.IncomingMessage,res:http.ServerResponse,c:{root:Buffer;store:HubStore;sessions:SessionLifecycle;clock:Clock;startedAt:number}){const u=new URL(req.url??"/","http://localhost");if(!u.pathname.startsWith("/v2/"))return false;authenticateRoot(req,c.root);if(req.method==="GET"&&u.pathname==="/v2/health"){sendJson(res,200,{protocolVersion:PROTOCOL_VERSION,pid:process.pid,startedAt:c.startedAt});return true}if(req.method==="POST"&&u.pathname==="/v2/sessions"){const b=await readJsonBody(req);validateBody(RegisterSessionRequestSchema,b);sendJson(res,200,c.sessions.registerSession(b as RegisterSessionRequest));return true}let m=u.pathname.match(/^\/v2\/sessions\/([^/]+)\/events$/);if(req.method==="POST"&&m){const b=await readJsonBody(req);validateBody(AppendEventsRequestSchema,b);sendJson(res,200,c.store.appendEvents(m[1]!,b as AppendEventsRequest));return true}m=u.pathname.match(/^\/v2\/sessions\/([^/]+)\/heartbeat$/);if(req.method==="POST"&&m){const b=await readJsonBody(req);validateBody(HeartbeatRequestSchema,b);sendJson(res,200,c.store.heartbeat(m[1]!,b as HeartbeatRequest));return true}m=u.pathname.match(/^\/v2\/sessions\/([^/]+)\/snapshot$/);if(req.method==="PUT"&&m){const b=await readJsonBody(req);validateBody(ReplaceSnapshotRequestSchema,b);sendJson(res,200,c.store.replaceSnapshot(m[1]!,b as ReplaceSnapshotRequest));return true}m=u.pathname.match(/^\/v2\/sessions\/([^/]+)$/);if(req.method==="DELETE"&&m){c.sessions.deleteSession(m[1]!);res.statusCode=204;res.end();return true}if(req.method==="POST"&&u.pathname==="/v2/query"){const b=await readJsonBody(req);validateBody(QueryRequestSchema,b);sendJson(res,200,queryActiveSessions(c.store,b as QueryRequest,c.clock.now()));return true}return false}
