import { createHash, randomBytes, randomUUID, timingSafeEqual } from "node:crypto";
import type { DatabaseSync, SQLInputValue } from "node:sqlite";
import type { Clock } from "../clock.js";
import { databaseSizeBytes } from "../schema.js";
import { MAX_DATABASE_BYTES } from "../store.js";
import { MAX_TASK_CONTENT_BYTES, validateMessage } from "./content.js";
import { CoordinationError } from "./errors.js";
import type { ClaimedDelivery, CoordinationMessage, CoordinationTask, CreateExistingTaskInput, CreateWorkerTaskInput, DeliveryRecord, TaskListFilters, TaskMutationResult, TaskPage, WorkerLaunchRecord } from "./types.js";

const terminal = new Set(["completed", "failed", "canceled", "rejected"]);
const digest = (token: string) => createHash("sha256").update(token, "utf8").digest();
interface TaskRow { id:string; instance_id:string; context_id:string; source_session_id:string; target_kind:"session"|"worker"; target_selector_json:string; target_session_id:string|null; state:CoordinationTask["state"]; cancellation_requested:number; source_closed:number; deadline_at:number; created_at:number; updated_at:number; terminal_code:string|null; content_bytes:number }
interface DeliveryRow { id:string; task_id:string; message_id:string; target_session_id:string; sequence:number; state:DeliveryRecord["state"]; claimed_at:number|null; acknowledged_at:number|null }

export class TaskStore {
  readonly instanceId: string;
  private readonly database: DatabaseSync; private readonly clock: Clock; private readonly maxDatabaseBytes: number; private readonly ownsDatabase: boolean;
  private readonly onProjectionChanged: (() => void) | undefined;
  constructor(options: { database?: DatabaseSync; clock: Clock; instanceId: string; maxDatabaseBytes?: number; onProjectionChanged?: (() => void) | undefined }) {
    if (!options.database) throw new Error("TaskStore requires the shared in-memory database");
    this.database=options.database; this.clock=options.clock; this.instanceId=options.instanceId; this.maxDatabaseBytes=options.maxDatabaseBytes ?? MAX_DATABASE_BYTES; this.ownsDatabase=false;
    this.onProjectionChanged=options?.onProjectionChanged;
  }
  isTaskFromCurrentInstance(id:string):boolean { return id.startsWith(`${this.instanceId}:`); }
  createExistingTask(input:CreateExistingTaskInput):{task:CoordinationTask;delivery:DeliveryRecord} {
    const taskId=`${this.instanceId}:${randomUUID()}`, deliveryId=randomUUID(), now=this.clock.now(), bytes=validateMessage(input.message);
    return this.tx(()=>{ this.enforceCreation(input.sourceSessionId,bytes); this.insertTask(taskId,input,"session",{type:"session",sessionId:input.targetSessionId},input.targetSessionId,bytes,now); this.insertMessage(taskId,input.message,1,bytes,now); const seq=this.nextDeliverySequence(input.targetSessionId); this.database.prepare("INSERT INTO a2a_deliveries(id,task_id,message_id,target_session_id,sequence,state) VALUES(?,?,?,?,?,'queued')").run(deliveryId,taskId,input.message.messageId,input.targetSessionId,seq); this.enforceDatabase(); return {task:this.getTask(taskId)!,delivery:this.delivery(deliveryId)!}; });
  }
  createRejectedTask(input:CreateExistingTaskInput, code:"TARGET_REJECTED"):CoordinationTask {
    const id=`${this.instanceId}:${randomUUID()}`,now=this.clock.now(),bytes=validateMessage(input.message);
    return this.tx(()=>{this.enforceCreation(input.sourceSessionId,bytes);this.insertTask(id,input,"session",{type:"session",sessionId:input.targetSessionId},undefined,bytes,now,"rejected",code);this.insertMessage(id,input.message,1,bytes,now);this.enforceDatabase();return this.getTask(id)!;});
  }
  createWorkerTask(input:CreateWorkerTaskInput):{task:CoordinationTask;launchToken:string} {
    const id=`${this.instanceId}:${randomUUID()}`,token=randomBytes(32).toString("hex"),now=this.clock.now(),bytes=validateMessage(input.message);
    return this.tx(()=>{this.enforceCreation(input.sourceSessionId,bytes);this.insertTask(id,input,"worker",{type:"worker",provider:input.provider,cwd:input.cwd,options:input.options},undefined,bytes,now);this.insertMessage(id,input.message,1,bytes,now);this.database.prepare("INSERT INTO worker_launches(task_id,provider,token_hash,state,deadline_at,created_at,updated_at) VALUES(?,?,?,'starting',?,?,?)").run(id,input.provider,digest(token),input.deadlineAt,now,now);this.enforceDatabase();return {task:this.getTask(id)!,launchToken:token};});
  }
  appendSourceMessage(taskId:string,message:CoordinationMessage):DeliveryRecord {
    return this.tx(()=>{const task=this.getTask(taskId);if(!task||terminal.has(task.state))throw new CoordinationError("TASK_NOT_FOUND","Task not found",404);const bytes=validateMessage(message);if(task.contentBytes+bytes>MAX_TASK_CONTENT_BYTES)throw new CoordinationError("TASK_CONTENT_LIMIT","Task content exceeds one MiB",413);if(!task.targetSessionId)throw new CoordinationError("TARGET_UNAVAILABLE","Target is unavailable",400);const mseq=this.nextMessageSequence(taskId);this.insertMessage(taskId,message,mseq,bytes,this.clock.now());const id=randomUUID(),dseq=this.nextDeliverySequence(task.targetSessionId);this.database.prepare("INSERT INTO a2a_deliveries(id,task_id,message_id,target_session_id,sequence,state) VALUES(?,?,?,?,?,'queued')").run(id,taskId,message.messageId,task.targetSessionId,dseq);this.database.prepare("UPDATE a2a_tasks SET content_bytes=content_bytes+?,updated_at=? WHERE id=?").run(bytes,this.clock.now(),taskId);this.enforceDatabase();return this.delivery(id)!;});
  }
  getTask(id:string):CoordinationTask|undefined { const row=this.database.prepare("SELECT * FROM a2a_tasks WHERE id=?").get(id) as TaskRow|undefined; return row?this.mapTask(row):undefined; }
  listTasks(source:string,filters:TaskListFilters={}):TaskPage {
    const size=filters.pageSize??50, clauses=["source_session_id = ?"],params:SQLInputValue[]=[source];
    if(filters.contextId){clauses.push("context_id = ?");params.push(filters.contextId)} if(filters.state){clauses.push("state = ?");params.push(filters.state)} if(filters.statusTimestampAfter!==undefined){clauses.push("updated_at > ?");params.push(filters.statusTimestampAfter)}
    if(filters.pageToken){let t:{updatedAt:number;id:string};try{t=JSON.parse(Buffer.from(filters.pageToken,"base64url").toString())}catch{throw new CoordinationError("UNSUPPORTED_CONTENT","Malformed page token",400)}if(!Number.isFinite(t.updatedAt)||typeof t.id!=="string")throw new CoordinationError("UNSUPPORTED_CONTENT","Malformed page token",400);clauses.push("(updated_at < ? OR (updated_at = ? AND id < ?))");params.push(t.updatedAt,t.updatedAt,t.id)}
    const where=clauses.join(" AND ");const rows=this.database.prepare(`SELECT * FROM a2a_tasks WHERE ${where} ORDER BY updated_at DESC,id DESC LIMIT ?`).all(...params,size+1) as unknown as TaskRow[];const total=(this.database.prepare(`SELECT COUNT(*) count FROM a2a_tasks WHERE ${where}`).get(...params) as {count:number}).count;const page=rows.slice(0,size),last=page.at(-1);return{tasks:page.map(r=>this.mapTask(r)),pageSize:size,totalSize:total,...(rows.length>size&&last?{nextPageToken:Buffer.from(JSON.stringify({updatedAt:last.updated_at,id:last.id})).toString("base64url")}:{})};
  }
  listMessages(id:string,historyLength?:number):CoordinationMessage[]{const rows=this.database.prepare("SELECT role,parts_json,extensions_json,message_id FROM a2a_messages WHERE task_id=? ORDER BY sequence").all(id) as Array<{role:"source"|"target";parts_json:string;extensions_json:string;message_id:string}>;const mapped=rows.map(r=>({messageId:r.message_id,role:r.role,parts:JSON.parse(r.parts_json),extensions:JSON.parse(r.extensions_json)}));return historyLength===undefined?mapped:mapped.slice(-historyLength)}
  listDeliveries(id:string):DeliveryRecord[]{return (this.database.prepare("SELECT * FROM a2a_deliveries WHERE task_id=? ORDER BY sequence").all(id) as unknown as DeliveryRow[]).map(r=>this.mapDelivery(r))}
  countTasks():number{return (this.database.prepare("SELECT COUNT(*) count FROM a2a_tasks").get() as {count:number}).count}
  listTasksForSession(sessionId:string,limit:number):Array<{id:string;role:"source"|"target";state:CoordinationTask["state"];createdAt:number;updatedAt:number}>{
    const rows=this.database.prepare(`SELECT id,source_session_id,target_session_id,state,created_at,updated_at FROM a2a_tasks WHERE source_session_id=? OR target_session_id=? ORDER BY updated_at DESC,id DESC LIMIT ?`).all(sessionId,sessionId,limit) as Array<{id:string;source_session_id:string;target_session_id:string|null;state:CoordinationTask["state"];created_at:number;updated_at:number}>;
    return rows.map(r=>({id:r.id,role:r.source_session_id===sessionId?"source" as const:"target" as const,state:r.state,createdAt:r.created_at,updatedAt:r.updated_at}));
  }
  countActiveTasks(source?:string):number{const states="('submitted','working')";const row=source?this.database.prepare(`SELECT COUNT(*) count FROM a2a_tasks WHERE state IN ${states} AND source_session_id=?`).get(source):this.database.prepare(`SELECT COUNT(*) count FROM a2a_tasks WHERE state IN ${states}`).get();return (row as {count:number}).count}
  claimNext(target:string,now:number):ClaimedDelivery|undefined{return this.tx(()=>{const active=this.database.prepare("SELECT 1 ok FROM a2a_deliveries WHERE target_session_id=? AND state IN ('claimed','accepted')").get(target);if(active)return undefined;const row=this.database.prepare("SELECT d.id FROM a2a_deliveries d JOIN a2a_tasks t ON t.id=d.task_id WHERE d.target_session_id=? AND d.state='queued' AND t.state IN ('submitted','working') AND t.cancellation_requested=0 AND t.deadline_at>? ORDER BY d.sequence LIMIT 1").get(target,now) as {id:string}|undefined;if(!row)return undefined;this.database.prepare("UPDATE a2a_deliveries SET state='claimed',claimed_at=? WHERE id=?").run(now,row.id);const d=this.delivery(row.id)!;this.database.prepare("UPDATE a2a_tasks SET state='working',updated_at=? WHERE id=? AND state='submitted'").run(now,d.taskId);const message=this.message(d.taskId,d.messageId)!;return{task:this.getTask(d.taskId)!,delivery:d,message,sourceLabel:"agent session"};});}
  abandonDelivery(target:string,id:string,now:number):string|undefined{return this.tx(()=>{const d=this.delivery(id);if(!d||d.targetSessionId!==target||d.state!=="claimed")return undefined;const task=this.getTask(d.taskId);if(!task)return undefined;if(task.deadlineAt<=now){this.database.prepare("UPDATE a2a_deliveries SET state='resolved' WHERE id=? AND state='claimed'").run(id);this.terminalTask(task.id,"failed","DEADLINE_EXCEEDED",now);this.deleteIfSourceClosed(task.id);return task.id}if(task.cancellationRequested){this.database.prepare("UPDATE a2a_deliveries SET state='resolved' WHERE id=? AND state='claimed'").run(id);this.terminalTask(task.id,"canceled",undefined,now);this.deleteIfSourceClosed(task.id);return task.id}this.database.prepare("UPDATE a2a_deliveries SET state='queued',claimed_at=NULL WHERE id=? AND state='claimed'").run(id);this.database.prepare("UPDATE a2a_tasks SET state='submitted',updated_at=? WHERE id=? AND state='working' AND NOT EXISTS (SELECT 1 FROM a2a_deliveries WHERE task_id=? AND id<>? AND state IN ('accepted','rejected','resolved'))").run(now,task.id,task.id,id);return task.id});}
  acceptDelivery(target:string,id:string,now:number):TaskMutationResult{return this.mutateDelivery(target,id,now,(d)=>this.database.prepare("UPDATE a2a_deliveries SET state='accepted',acknowledged_at=? WHERE id=?").run(now,d.id))}
  rejectDelivery(target:string,id:string,code:string,now:number):TaskMutationResult{return this.mutateDelivery(target,id,now,(d)=>{this.database.prepare("UPDATE a2a_deliveries SET state='rejected',acknowledged_at=? WHERE id=?").run(now,d.id);this.terminalTask(d.taskId,"rejected",code,now)})}
  appendTargetMessage(taskId:string,message:CoordinationMessage):void{this.tx(()=>{this.addTargetMessage(taskId,message);this.enforceDatabase()})}
  resolveDelivery(target:string,id:string,now:number):void{this.mutateDelivery(target,id,now,d=>this.database.prepare("UPDATE a2a_deliveries SET state='resolved',acknowledged_at=? WHERE id=?").run(now,d.id))}
  completeDelivery(target:string,id:string,message:CoordinationMessage,now:number):TaskMutationResult{return this.mutateDelivery(target,id,now,d=>{const task=this.getTask(d.taskId)!;if(terminal.has(task.state))return;this.addTargetMessage(d.taskId,message);this.database.prepare("UPDATE a2a_deliveries SET state='resolved',acknowledged_at=? WHERE id=?").run(now,id);const queued=this.database.prepare("SELECT 1 ok FROM a2a_deliveries WHERE task_id=? AND state='queued'").get(d.taskId);if(!queued)this.terminalTask(d.taskId,"completed",undefined,now)})}
  failDelivery(target:string,id:string,code:string,message:CoordinationMessage|undefined,now:number):TaskMutationResult{return this.mutateDelivery(target,id,now,d=>{const task=this.getTask(d.taskId)!;if(terminal.has(task.state))return;if(message)this.addTargetMessage(d.taskId,message);this.database.prepare("UPDATE a2a_deliveries SET state='resolved',acknowledged_at=? WHERE id=?").run(now,id);this.terminalTask(d.taskId,"failed",code,now)})}
  requestCancellation(source:string,id:string,now:number):CoordinationTask{return this.tx(()=>{const task=this.getTask(id);if(!task||task.sourceSessionId!==source)throw new CoordinationError("TASK_NOT_FOUND","Task not found",404);if(terminal.has(task.state))throw new CoordinationError("TASK_NOT_CANCELABLE","Task is not cancelable",400);const claimed=this.database.prepare("SELECT 1 ok FROM a2a_deliveries WHERE task_id=? AND state IN ('claimed','accepted')").get(id);if(claimed)this.database.prepare("UPDATE a2a_tasks SET cancellation_requested=1,updated_at=? WHERE id=?").run(now,id);else{this.database.prepare("UPDATE a2a_deliveries SET state='resolved' WHERE task_id=? AND state='queued'").run(id);this.terminalTask(id,"canceled",undefined,now)}return this.getTask(id)!;})}
  acknowledgeCanceled(target:string,id:string,now:number):TaskMutationResult{return this.tx(()=>{const task=this.getTask(id);if(!task||task.targetSessionId!==target)throw new CoordinationError("TASK_NOT_FOUND","Task not found",404);if(!terminal.has(task.state)&&task.cancellationRequested)this.terminalTask(id,"canceled",undefined,now);this.database.prepare("UPDATE a2a_deliveries SET state='resolved',acknowledged_at=? WHERE task_id=? AND target_session_id=? AND state IN ('claimed','accepted')").run(now,id,target);const updated=this.getTask(id)!;return{task:updated,cancellationRequested:updated.cancellationRequested}})}
  expireDeadlines(now:number):string[]{return this.tx(()=>{const rows=this.database.prepare("SELECT id FROM a2a_tasks WHERE state IN ('submitted','working') AND deadline_at<=?").all(now) as Array<{id:string}>;for(const r of rows){this.database.prepare("UPDATE a2a_deliveries SET state='resolved' WHERE task_id=? AND state IN ('queued','claimed','accepted')").run(r.id);this.terminalTask(r.id,"failed","DEADLINE_EXCEEDED",now)}return rows.map(r=>r.id)})}
  closeSourceSession(id:string,now:number):string[]{return this.tx(()=>{const rows=this.database.prepare("SELECT id,state FROM a2a_tasks WHERE source_session_id=?").all(id) as Array<{id:string;state:string}>;const affected:string[]=[];for(const r of rows){if(terminal.has(r.state)){this.database.prepare("DELETE FROM a2a_tasks WHERE id=?").run(r.id);continue}this.database.prepare("UPDATE a2a_tasks SET source_closed=1,updated_at=? WHERE id=?").run(now,r.id);const claimed=this.database.prepare("SELECT 1 FROM a2a_deliveries WHERE task_id=? AND state IN ('claimed','accepted')").get(r.id);if(claimed)this.database.prepare("UPDATE a2a_tasks SET cancellation_requested=1 WHERE id=?").run(r.id);else{this.database.prepare("UPDATE a2a_deliveries SET state='resolved' WHERE task_id=?").run(r.id);this.terminalTask(r.id,"canceled",undefined,now);this.database.prepare("DELETE FROM a2a_tasks WHERE id=?").run(r.id)}affected.push(r.id)}return affected})}
  closeTargetSession(id:string,now:number):string[]{return this.tx(()=>{const rows=this.database.prepare("SELECT DISTINCT task_id,state FROM a2a_deliveries WHERE target_session_id=? AND state IN ('queued','claimed','accepted')").all(id) as Array<{task_id:string;state:string}>;for(const r of rows){this.database.prepare("UPDATE a2a_deliveries SET state='resolved' WHERE task_id=? AND target_session_id=?").run(r.task_id,id);this.terminalTask(r.task_id,"failed",r.state==='queued'?"TARGET_UNAVAILABLE":"DELIVERY_LOST",now);this.deleteIfSourceClosed(r.task_id)}return rows.map(r=>r.task_id)})}
  countRetainedTasks():number{return this.countTasks()}
  recordWorkerStarted(id:string,launchId:string):void{this.tx(()=>{this.database.prepare("UPDATE worker_launches SET launch_id=?,state='started',updated_at=? WHERE task_id=? AND state='starting'").run(launchId,this.clock.now(),id)})}
  recordWorkerStartFailed(id:string,code:string):void{this.tx(()=>{this.database.prepare("UPDATE worker_launches SET state='failed',updated_at=? WHERE task_id=? AND state IN ('starting','started')").run(this.clock.now(),id);this.terminalTask(id,"failed",code,this.clock.now());this.deleteIfSourceClosed(id)})}
  bindWorkerSession(token:string,session:string):CoordinationTask{return this.tx(()=>{if(!/^[0-9a-f]{64}$/.test(token))throw new CoordinationError("LAUNCH_TOKEN_INVALID","Launch token is invalid or expired",401);const candidate=digest(token),rows=this.database.prepare("SELECT task_id,token_hash FROM worker_launches WHERE state IN ('starting','started')").all() as Array<{task_id:string;token_hash:Uint8Array}>;const row=rows.find(r=>{const stored=Buffer.from(r.token_hash);return stored.length===candidate.length&&timingSafeEqual(stored,candidate)});if(!row)throw new CoordinationError("LAUNCH_TOKEN_INVALID","Launch token is invalid or expired",401);const task=this.getTask(row.task_id)!;this.database.prepare("UPDATE worker_launches SET state='bound',bound_session_id=?,updated_at=? WHERE task_id=?").run(session,this.clock.now(),task.id);this.database.prepare("UPDATE a2a_tasks SET target_session_id=?,updated_at=? WHERE id=?").run(session,this.clock.now(),task.id);const first=this.listMessages(task.id)[0]!;this.database.prepare("INSERT INTO a2a_deliveries(id,task_id,message_id,target_session_id,sequence,state) VALUES(?,?,?,?,?,'queued')").run(randomUUID(),task.id,first.messageId,session,this.nextDeliverySequence(session));return this.getTask(task.id)!;})}
  listExpiredWorkerLaunches(now:number):WorkerLaunchRecord[]{return (this.database.prepare("SELECT task_id,provider,launch_id,state,deadline_at,bound_session_id FROM worker_launches WHERE state IN ('starting','started') AND deadline_at<=?").all(now) as Array<{task_id:string;provider:string;launch_id:string|null;state:WorkerLaunchRecord['state'];deadline_at:number;bound_session_id:string|null}>).map(r=>({taskId:r.task_id,provider:r.provider,state:r.state,deadlineAt:r.deadline_at,...(r.launch_id?{launchId:r.launch_id}:{}),...(r.bound_session_id?{boundSessionId:r.bound_session_id}:{})}))}
  getWorkerLaunch(taskId:string):WorkerLaunchRecord|undefined{const r=this.database.prepare("SELECT task_id,provider,launch_id,state,deadline_at,bound_session_id FROM worker_launches WHERE task_id=?").get(taskId) as {task_id:string;provider:string;launch_id:string|null;state:WorkerLaunchRecord['state'];deadline_at:number;bound_session_id:string|null}|undefined;return r?{taskId:r.task_id,provider:r.provider,state:r.state,deadlineAt:r.deadline_at,...(r.launch_id?{launchId:r.launch_id}:{}),...(r.bound_session_id?{boundSessionId:r.bound_session_id}:{})}:undefined}
  close():void{if(this.ownsDatabase)this.database.close()}
  private tx<T>(fn:()=>T):T{this.database.exec("BEGIN IMMEDIATE");try{const v=fn();this.database.exec("COMMIT");this.onProjectionChanged?.();return v}catch(e){this.database.exec("ROLLBACK");throw e}}
  private enforceCreation(source:string,bytes:number){if(bytes>MAX_TASK_CONTENT_BYTES)throw new CoordinationError("TASK_CONTENT_LIMIT","Task content exceeds one MiB",413);if(this.countActiveTasks(source)>=50||this.countActiveTasks()>=500)throw new CoordinationError("TASK_COUNT_LIMIT","Active task limit exceeded",429)}
  private enforceDatabase(){if(databaseSizeBytes(this.database)>this.maxDatabaseBytes)throw new CoordinationError("DATABASE_LIMIT","Coordination database budget exceeded",429)}
  private insertTask(id:string,input:{sourceSessionId:string;contextId:string;deadlineAt:number},kind:string,target:unknown,targetSession:string|undefined,bytes:number,now:number,state="submitted",code?:string){this.database.prepare("INSERT INTO a2a_tasks(id,instance_id,context_id,source_session_id,target_kind,target_selector_json,target_session_id,state,deadline_at,created_at,updated_at,terminal_code,content_bytes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)").run(id,this.instanceId,input.contextId,input.sourceSessionId,kind,JSON.stringify(target),targetSession??null,state,input.deadlineAt,now,now,code??null,bytes)}
  private insertMessage(id:string,m:CoordinationMessage,seq:number,bytes:number,now:number){this.database.prepare("INSERT INTO a2a_messages(task_id,message_id,sequence,role,parts_json,extensions_json,created_at,content_bytes) VALUES(?,?,?,?,?,?,?,?)").run(id,m.messageId,seq,m.role,JSON.stringify(m.parts),JSON.stringify(m.extensions),now,bytes)}
  private nextMessageSequence(id:string):number{return ((this.database.prepare("SELECT COALESCE(MAX(sequence),0)+1 n FROM a2a_messages WHERE task_id=?").get(id) as {n:number}).n)}
  private nextDeliverySequence(target:string):number{return ((this.database.prepare("SELECT COALESCE(MAX(sequence),0)+1 n FROM a2a_deliveries WHERE target_session_id=?").get(target) as {n:number}).n)}
  private delivery(id:string):DeliveryRecord|undefined{const r=this.database.prepare("SELECT * FROM a2a_deliveries WHERE id=?").get(id) as DeliveryRow|undefined;return r?this.mapDelivery(r):undefined}
  private message(task:string,id:string):CoordinationMessage|undefined{return this.listMessages(task).find(m=>m.messageId===id)}
  private mapDelivery(r:DeliveryRow):DeliveryRecord{return{id:r.id,taskId:r.task_id,messageId:r.message_id,targetSessionId:r.target_session_id,sequence:r.sequence,state:r.state,...(r.claimed_at!==null?{claimedAt:r.claimed_at}:{}),...(r.acknowledged_at!==null?{acknowledgedAt:r.acknowledged_at}:{})}}
  private mapTask(r:TaskRow):CoordinationTask{return{id:r.id,instanceId:r.instance_id,contextId:r.context_id,sourceSessionId:r.source_session_id,target:JSON.parse(r.target_selector_json),...(r.target_session_id?{targetSessionId:r.target_session_id}:{}),state:r.state,cancellationRequested:Boolean(r.cancellation_requested),sourceClosed:Boolean(r.source_closed),deadlineAt:r.deadline_at,createdAt:r.created_at,updatedAt:r.updated_at,...(r.terminal_code?{terminalCode:r.terminal_code}:{}),contentBytes:r.content_bytes}}
  private addTargetMessage(id:string,m:CoordinationMessage){const task=this.getTask(id);if(!task||terminal.has(task.state))return;const bytes=validateMessage(m);if(task.contentBytes+bytes>MAX_TASK_CONTENT_BYTES)throw new CoordinationError("TASK_CONTENT_LIMIT","Task content exceeds one MiB",413);this.insertMessage(id,{...m,role:"target"},this.nextMessageSequence(id),bytes,this.clock.now());this.database.prepare("UPDATE a2a_tasks SET content_bytes=content_bytes+?,updated_at=? WHERE id=?").run(bytes,this.clock.now(),id)}
  private mutateDelivery(target:string,id:string,now:number,fn:(d:DeliveryRecord)=>void):TaskMutationResult{return this.tx(()=>{const d=this.delivery(id);if(!d||d.targetSessionId!==target)throw new CoordinationError("DELIVERY_NOT_FOUND","Delivery not found",404);const existing=this.getTask(d.taskId);if(!['claimed','accepted'].includes(d.state)){if(existing&&terminal.has(existing.state))return{task:existing,cancellationRequested:existing.cancellationRequested};throw new CoordinationError("DELIVERY_NOT_FOUND","Delivery not found",404)}fn(d);const task=this.getTask(d.taskId)!;this.deleteIfSourceClosed(task.id);const current=this.getTask(task.id)??task;return{task:current,cancellationRequested:current.cancellationRequested}})}
  private terminalTask(id:string,state:CoordinationTask['state'],code:string|undefined,now:number){this.database.prepare("UPDATE a2a_tasks SET state=?,terminal_code=?,updated_at=? WHERE id=? AND state IN ('submitted','working')").run(state,code??null,now,id)}
  private deleteIfSourceClosed(id:string){const t=this.getTask(id);if(t?.sourceClosed&&terminal.has(t.state))this.database.prepare("DELETE FROM a2a_tasks WHERE id=?").run(id)}
}
